Lemma shadow_words_mapped (M : word -> option byte) p n :
  (forall x, (LOWSH_LO <= x < LOWSH_HI \/ HIGHSH_LO <= x < HIGHSH_HI) -> M (Z_to_bv 64 x) <> None) ->
  0 < n -> XIA.app8 p n ->
  forall x, 8 * ((0x7fff8000 + p / 8) / 8) <= x < 8 * ((0x7fff8000 + (p + n - 1) / 8) / 8) + 8 -> M (Z_to_bv 64 x) <> None.
