z_msgpack_encoder.lib.Mh_0179.L5DefsA OSSVerify.Proofs.jsoncons.fuzz_msgpack_encoder.lib.asan.Mh_0210.L5CoreA OSSVerify.Proofs.jsoncons.fuzz_msgpack_encoder.lib.asan.Mh_0210.L5StepAR OSSVerify.Proofs.jsoncons.fuzz_msgpack_encoder.lib.Mh_0018.PmLayout OSSVerify.Proofs.jsoncons.fuzz_msgpack_encoder.lib.Mh_0024.PmLayoutA OSSVerify.Proofs.jsoncons.fuzz_msgpack_encoder.lib.Mh_0024.PnLayoutA OSSVerify.Proofs.jsoncons.fuzz_msgpack_encoder.lib.Mh_0090.PmModel OSSVerify.Proofs.jsoncons.fuzz_msgpack_encoder.lib.Mh_0090.PmStatics OSSVerify.Proofs.jsoncons.fuzz_msgpack_encoder.lib.Mh_0092.PmStaticsA OSSVerify.Proofs.jsoncons.fuzz_msgpack_encoder.lib.Mh_0089.HeapIfaceAMx OSSVerify.Proofs.jsoncons.fuzz_msgpack_encoder.lib.Mh_0090.PmSpecs OSSVerify.Proofs.jsoncons.fuzz_msgpack_encoder.lib.Mh_0213.PmSpecsA OSSVerify.Proofs.jsoncons.fuzz_msgpack_encoder.lib.Mh_0213.PmSpecsAX OSSVerify.Proofs.jsoncons.fuzz_msgpack_encoder.lib.Mh_0213.PnSpecsAX OSSVerify.Proofs.jsoncons.fuzz_msgpack_encoder.lib.Mh_0213.PnSpecsAa OSSVerify.Proofs.jsoncons.fuzz_msgpack_encoder.lib.Mh_0090.PgSrc OSSVerify.Proofs.jsoncons.fuzz_msgpack_encoder.lib.PgV8 OSSVerify.Proofs.jsoncons.fuzz_msgpack_encoder.lib.Mh_0213.PgSrcA OSSVerify.Proofs.jsoncons.fuzz_msgpack_encoder.lib.Mh_0213.PgV8A OSSVerify.Proofs.jsoncons.fuzz_msgpack_encoder.lib.Mh_0018.PnLayoutQ OSSVerify.Proofs.jsoncons.fuzz_msgpack_encoder.lib.Mh_0024.PnLayoutQA OSSVerify.Proofs.jsoncons.fuzz_msgpack_encoder.lib.Mh_0092.PnQStaticsA OSSVerify.Proofs.jsoncons.fuzz_msgpack_encoder.lib.Mh_0092.PnModelA OSSVerify.Proofs.jsoncons.fuzz_msgpack_encoder.lib.Mh_0213.PnRunA OSSVerify.Proofs.jsoncons.fuzz_msgpack_encoder.lib.Mh_0213.PnRunHA OSSVerify.Proofs.jsoncons.fuzz_msgpack_encoder.lib.Mh_0213.PnRunAa OSSVerify.Proofs.jsoncons.fuzz_msgpack_encoder.lib.Mh_0213.PnSpecsAXq.
Import ListNotations. Local Ltac Zify.zify_convert_to_euclidean_division_equations_flag ::= constr:(false).
Open Scope Z_scope.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.

Module PQAPCS.
Abbreviation reg i := (Z_to_bv 5 (Z.of_nat i)).
Abbreviation RSEGS := Asan.M.loaded_segments.
Definition SCR : Z := 24576.                       (* [comment removed for export] *)
Definition mparser_at := (PQMA.mparser_at RSEGS PMA.AD PMSPA.accA PMSPA.annA (pa_vp_parser PMA.AD)).

Section Call.
Context {SCFG_P : ScfgP}.
Variables (L : asan_layout) (ar : asan_run) (HI : asan_iface).
Variables (R0 : bvmap 5 word) (M0 : word -> option byte) (model0 : Model) (K : TSet).
Variables (LB : list (Z * Z)) (FF LK0 : list fframe) (Aw0 : list (Z * Z)) (cr : credit) (sp r fb oo : Z).

Definition op : Z := fb + 592.
Definition cost : credit := PMSPA.scA L (PM.credit_add (PM.cost1 (PMSPA.HV L ar) PM.CHUNK) (PM.cost1 (PMSPA.HV L ar) 24)).

(* [comment removed for export] *)
Definition pre : Prop :=
  ri_inv HI LB FF LK0 cr Aw0 M0 (vml_of model0) /\ L5CA.amodel_ok Aw0 model0 /\ K [] /\ PMSPA.entryA PMA.AD L ar R0 M0 sp r 6
  /\ PGSA.ffroomB PQRA.FCM 6 FF LK0 /\ PMSPA.ffrsA FF sp /\ PQRA.frame_okM FF fb
  /\ getr R0 (reg 10) = Z_to_bv 64 op /\ getr R0 (reg 11) = Z_to_bv 64 (fb + 96) /\ getr R0 (reg 12) = Z_to_bv 64 oo
  /\ PMSPA.aobjA FF oo 24 /\ (oo + 24 <= op \/ op + 504 <= oo) /\ oo mod 8 = 0
  /\ L5.defined M0 op 400 /\ PMSPA.accA M0 op 400 /\ PMSPA.accA M0 oo 24
  /\ L5.u64_at RSEGS M0 oo (pa_vp_opts PMA.AD) /\ L5.u32_at RSEGS M0 (oo + 16) 1024 /\ L5.defined M0 oo 24
  /\ L5.u64_at RSEGS M0 (fb + 96) (pa_vp_iss PMA.AD) /\ L5.u64_at RSEGS M0 (fb + 256) (fb + 112) /\ PMSPA.accA M0 (fb + 96) 272
  /\ PMSTA.base_okA RSEGS PMA.AD M0 /\ PMST.loc_ok RSEGS PMA.AD M0 true
  /\ PMSP.credit_le cost cr.

(* [comment removed for export] *)
Definition kont : Prop :=
  forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (LK' : list fframe) (Aw' : list (Z * Z)) (qc b : Z) (cr' : credit),
    regs_preserved R0 R' -> mparser_at M' op (fb + 96) (PQRHA.mparser_init qc b) ->
    L5CA.ahpres L ar LB FF sp (PMSPA.pm_scr 6) [(op, 400)] M0 M' ->
    PMSP.credit_keep cr cr' cost (PMSPA.scA L PMSP.cr0) ->
    model_rt model0 model' -> incl LK' LK0 -> incl Aw0 Aw' -> L5CA.amodel_ok Aw' model' ->
    ri_inv HI (PQMA.mparser_own (PQRHA.mparser_init qc b) ++ LB) FF LK' cr' Aw' M' (vml_of model') ->
    srealizes RSEGS SCFG (PMSPA.cfg RSEGS (fx:=fx') R' r M' model') K.

(* [comment removed for export] *)
Definition saves_rd (M : word -> option byte) : Prop :=
  L5.u64_at RSEGS M (sp - 8) (bv_unsigned (getr R0 (reg 1))) /\ L5.u64_at RSEGS M (sp - 16) (bv_unsigned (getr R0 (reg 8)))
  /\ L5.u64_at RSEGS M (sp - 24) (bv_unsigned (getr R0 (reg 9))) /\ L5.u64_at RSEGS M (sp - 32) (bv_unsigned (getr R0 (reg 18)))
  /\ L5.u64_at RSEGS M (sp - 40) (bv_unsigned (getr R0 (reg 19))) /\ L5.u64_at RSEGS M (sp - 48) (bv_unsigned (getr R0 (reg 20)))
  /\ L5.u64_at RSEGS M (sp - 56) (bv_unsigned (getr R0 (reg 21))) /\ L5.u64_at RSEGS M (sp - 64) (bv_unsigned (getr R0 (reg 22))).
(* [comment removed for export] *)
Definition saves_src (M : word -> option byte) : Prop :=
  L5.u64_at RSEGS M (sp - 88) 0xcec5c /\ L5.u64_at RSEGS M (sp - 96) op /\ L5.u64_at RSEGS M (sp - 104) (op + 24)
  /\ L5.u64_at RSEGS M (sp - 112) oo /\ L5.u64_at RSEGS M (sp - 120) (bv_unsigned (getr R0 (reg 19))).
(* [comment removed for export] *)
Definition saves_nis (M : word -> option byte) : Prop :=
  L5.u64_at RSEGS M (sp - 136) 0xcf028 /\ L5.u64_at RSEGS M (sp - 144) (op + 32) /\ L5.u64_at RSEGS M (sp - 152) (op + 24)
  /\ L5.u64_at RSEGS M (sp - 160) (fb + 96) /\ L5.u64_at RSEGS M (sp - 168) 2147450880 /\ L5.u64_at RSEGS M (sp - 176) (bv_unsigned (getr R0 (reg 20)))
  /\ L5.u64_at RSEGS M (sp - 184) 2147450880.
(* [comment removed for export] *)
Definition hcells (M : word -> option byte) : Prop :=
  L5.u64_at RSEGS M op (pa_vp_parser PMA.AD) /\ L5.u8_at RSEGS M (op + 8) 1 /\ L5.u8_at RSEGS M (op + 9) 0
  /\ L5.u32_at RSEGS M (op + 12) 0 /\ L5.u8_at RSEGS M (op + 16) 0 /\ L5.u32_at RSEGS M (op + 20) 0
  /\ L5.u64_at RSEGS M (op + 32) (pa_vp_nullis PMA.AD) /\ L5.u64_at RSEGS M (op + 56) (pa_classic_imp PMA.AD)
  /\ L5.u64_at RSEGS M (op + 112) (pa_vp_nullis_ios PMA.AD) /\ L5.u32_at RSEGS M (op + 144) 0 /\ L5.u32_at RSEGS M (op + 148) 0
  /\ L5.u64_at RSEGS M (op + 152) (op + 48) /\ L5.u64_at RSEGS M (op + 160) (pa_classic_imp PMA.AD) /\ PM.zeros_at M (op + 168) 80.

(* [comment removed for export] *)
Definition rmidc (M : word -> option byte) (model : Model) (LK : list fframe) (Aw : list (Z * Z)) : Prop :=
  saves_rd M /\ saves_src M /\ hcells M
  /\ L5.defined M op 400 /\ PMSPA.accA M op 400 /\ PMSPA.accA M oo 24
  /\ L5.u64_at RSEGS M oo (pa_vp_opts PMA.AD) /\ L5.u32_at RSEGS M (oo + 16) 1024
  /\ PMSPA.accA M (fb + 96) 272
  /\ L5CA.astk ar M sp SCR /\ shadow_zero M (sp - SCR) (SCR / 8)
  /\ PMSTA.base_okA RSEGS PMA.AD M /\ PMST.loc_ok RSEGS PMA.AD M true
  /\ ri_inv HI LB FF LK cr Aw M (vml_of model) /\ L5CA.amodel_ok Aw model /\ model_rt model0 model /\ incl LK LK0 /\ incl Aw0 Aw
  /\ L5SAR.ek L ar LB FF sp SCR [(op, 400)] M0 M /\ L5SAR.dk L ar LB FF sp SCR M0 M.

(* [comment removed for export] *)
Definition rmid1 (R : bvmap 5 word) (M : word -> option byte) (model : Model) (LK : list fframe) (Aw : list (Z * Z)) : Prop :=
  getr R (reg 2) = Z_to_bv 64 (sp - 192) /\ getr R (reg 8) = Z_to_bv 64 (op + 32) /\ getr R (reg 9) = Z_to_bv 64 (op + 48)
  /\ getr R (reg 18) = Z_to_bv 64 (op + 112) /\ getr R (reg 19) = Z_to_bv 64 ((op + 48) / 8 + 2147450880)
  /\ getr R (reg 20) = Z_to_bv 64 ((op + 32) / 8 + 2147450880) /\ getr R (reg 21) = Z_to_bv 64 ((op + 112) / 8 + 2147450880)
  /\ (forall k, In k [3; 4; 22; 23; 24; 25; 26; 27]%nat -> getr R (reg k) = getr R0 (reg k))
  /\ L5.u64_at RSEGS M (fb + 96) (pa_vp_iss PMA.AD) /\ L5.u64_at RSEGS M (fb + 256) (fb + 112)
  /\ saves_nis M /\ rmidc M model LK Aw.

(* [comment removed for export] *)
Definition rmid2 (R : bvmap 5 word) (M : word -> option byte) (model : Model) (LK : list fframe) (Aw : list (Z * Z)) : Prop :=
  getr R (reg 2) = Z_to_bv 64 (sp - 128) /\ getr R (reg 8) = Z_to_bv 64 (op + 32) /\ getr R (reg 9) = Z_to_bv 64 (op + 24)
  /\ getr R (reg 18) = Z_to_bv 64 (op + 304) /\ getr R (reg 19) = Z_to_bv 64 2147450880 /\ getr R (reg 21) = Z_to_bv 64 2147450880
  /\ (forall k, In k [3; 4; 20; 22; 23; 24; 25; 26; 27]%nat -> getr R (reg k) = getr R0 (reg k))
  /\ L5.u64_at RSEGS M (op + 48) (pa_vp_nullbuf PMA.AD) /\ L5.u64_at RSEGS M (op + 264) (fb + 96) /\ L5.u64_at RSEGS M (op + 272) (fb + 112)
  /\ PM.zeros_at M (op + 280) 16 /\ L5.u64_at RSEGS M (op + 296) PM.CHUNK /\ PM.zeros_at M (op + 304) 16
  /\ rmidc M model LK Aw.

End Call.
End PQAPCS.

(* [comment removed for export] *)
Module PQAPCSG.
Import PQAPCS. Local Ltac Zify.zify_convert_to_euclidean_division_equations_flag ::= constr:(false).
Section Spec.
Context {SCFG_P : ScfgP}.
Variables (L : asan_layout) (ar : asan_run) (HI : asan_iface).
Lemma spec_of : (forall (fx : FPState) R M model K LB FF LK Aw cr sp r fb oo,
   pre L ar HI R M model K LB FF LK Aw cr sp r fb oo -> kont L ar HI R M model K LB FF LK Aw cr sp r fb ->
   srealizes RSEGS SCFG (PMSPA.cfg RSEGS (fx:=fx) R 0xceb7c M model) K) -> PQRAa.parser_ctor_spec L ar HI.
Proof.
  intros HK. unfold PQRAa.parser_ctor_spec, PQRHA.parser_ctor_spec.
  intros fx R M model K LB FF LK Aw cr sp r fb oo HH AM K0 ENT FRM FRS SP16 FOK A10 A11 A12 AOO APART O8 (OP0 & OP16 & OPD) ACCO DEF ACC (IS0 & IS160) ACCI BASE LOC CRED KONT.
  apply (HK fx R M model K LB FF LK Aw cr sp r fb oo).
  - unfold pre, op. replace (fb + 256) with (fb + 96 + 160) by (clear; lia). replace (fb + 112) with (fb + 96 + 16) by (clear; lia).
    exact (conj HH (conj AM (conj K0 (conj ENT (conj FRM (conj FRS (conj FOK (conj A10 (conj A11 (conj A12 (conj AOO (conj APART (conj O8
           (conj DEF (conj ACC (conj ACCO (conj OP0 (conj OP16 (conj OPD (conj IS0 (conj IS160 (conj ACCI (conj BASE (conj LOC CRED)))))))))))))))))))))))).
  - exact KONT.
Qed.
End Spec.
End PQAPCSG.

